import { useFrame } from '@react-three/fiber'
import { useEffect, useRef } from 'react'
import * as THREE from 'three'
import { deterministicAimSeed, getDifficulty, normalizedLevelProgress, predictAimTarget } from './difficulty'
import type { EnemyHandle, EnemySpawn, PlayerState, WorldState } from './types'

interface EnemyProps {
  spawn: EnemySpawn
  world: WorldState
  onExpired: (spawn: EnemySpawn) => void
  player: PlayerState
  onFire: (position: THREE.Vector3, direction: THREE.Vector3, speed: number) => void
  register: (handle: EnemyHandle) => void
  unregister: (id: string) => void
}

export function Enemy({ spawn, world, player, onExpired, onFire, register, unregister }: EnemyProps) {
  const group = useRef<THREE.Group>(null)
  const lastFire = useRef(0)
  const shotCount = useRef(0)
  const handle = useRef<EnemyHandle>({
    id: spawn.id,
    variant: spawn.variant,
    position: new THREE.Vector3(spawn.x, spawn.y, spawn.z),
    previousPosition: new THREE.Vector3(spawn.x, spawn.y, spawn.z),
    // The carrier's glowing core is the readable, fair hit area rather than
    // making every wing and tower an accidental hit target.
    radius: spawn.variant === 'carrier' ? 2.35 : 1.1,
    alive: true,
  })

  useEffect(() => {
    register(handle.current)
    return () => unregister(spawn.id)
  }, [register, spawn.id, unregister])

  useFrame(({ clock }, delta) => {
    if (!group.current || !handle.current.alive) return
    const age = world.distance - spawn.bornAt
    handle.current.previousPosition.copy(handle.current.position)
    const carrierRatio = spawn.variant === 'carrier' ? spawn.health / Math.max(1, spawn.maxHealth) : 1
    const carrierPhase = carrierRatio <= 0.33 ? 2 : carrierRatio <= 0.66 ? 1 : 0
    group.current.position.set(
      spawn.x + (spawn.variant === 'carrier' ? Math.sin(clock.elapsedTime * (0.8 + carrierPhase * 0.18)) * (3.4 + carrierPhase * 0.4) : 0),
      spawn.y + (spawn.variant === 'carrier' ? Math.sin(clock.elapsedTime * (0.55 + carrierPhase * 0.12)) * (1.2 + carrierPhase * 0.2) : 0),
      spawn.z + age,
    )
    group.current.rotation.y += delta * (spawn.variant === 'carrier' ? 0.2 + carrierPhase * 0.2 : 1.8)
    handle.current.position.copy(group.current.position)

    const difficulty = getDifficulty(normalizedLevelProgress(world.distance))
    const baseCadence = spawn.variant === 'carrier'
      ? [1.7, 1.25, 0.88][carrierPhase]
      : spawn.variant === 'heavy' ? 2.1 : spawn.variant === 'turret' ? 2.45 : 2.3
    const cadence = baseCadence * difficulty.fireIntervalMultiplier
    if (group.current.position.z > -28 && group.current.position.z < 7 && world.time - lastFire.current > cadence) {
      lastFire.current = world.time
      const origin = group.current.position.clone().add(new THREE.Vector3(0, 0, 1.4))
      const seed = deterministicAimSeed(spawn.id, shotCount.current++)
      const predicted = predictAimTarget(player.position, player.velocity, origin, difficulty, seed)
      const direction = new THREE.Vector3(predicted.x, predicted.y, player.position.z).sub(origin).normalize()
      onFire(origin, direction, difficulty.projectileSpeed)
    }
    if (group.current.position.z > 12) {
      handle.current.alive = false
      onExpired(spawn)
    }
  })

  if (spawn.variant === 'carrier') {
    const ratio = spawn.health / Math.max(1, spawn.maxHealth)
    return <Carrier group={group} phase={ratio <= 0.33 ? 2 : ratio <= 0.66 ? 1 : 0} />
  }
  if (spawn.variant === 'turret') return <Turret group={group} />
  if (spawn.variant === 'heavy') return <Heavy group={group} />
  return <Scout group={group} />
}

function Scout({ group }: { group: React.RefObject<THREE.Group | null> }) {
  return (
    <group ref={group}>
      <mesh rotation={[Math.PI / 2, 0, 0]}>
        <coneGeometry args={[0.48, 1.8, 4]} />
        <meshStandardMaterial color="#d45c5b" metalness={0.75} roughness={0.3} emissive="#591b2d" emissiveIntensity={0.8} flatShading />
      </mesh>
      <mesh position={[0, 0, -0.25]} rotation={[0, 0, Math.PI / 2]}>
        <boxGeometry args={[2.1, 0.08, 0.46]} />
        <meshStandardMaterial color="#9d344c" metalness={0.8} roughness={0.3} emissive="#3f1728" emissiveIntensity={0.8} flatShading />
      </mesh>
      <pointLight color="#ff544f" intensity={1.3} distance={4} />
    </group>
  )
}

function Heavy({ group }: { group: React.RefObject<THREE.Group | null> }) {
  return (
    <group ref={group}>
      <mesh>
        <octahedronGeometry args={[1.25, 0]} />
        <meshStandardMaterial color="#a84748" metalness={0.88} roughness={0.35} emissive="#4e1a23" emissiveIntensity={0.75} flatShading />
      </mesh>
      <mesh scale={[1.7, 0.16, 0.45]}>
        <boxGeometry />
        <meshStandardMaterial color="#e17b55" metalness={0.7} roughness={0.35} emissive="#551f25" emissiveIntensity={0.7} flatShading />
      </mesh>
      <pointLight color="#ff7a51" intensity={2} distance={5} />
    </group>
  )
}

function Turret({ group }: { group: React.RefObject<THREE.Group | null> }) {
  return (
    <group ref={group}>
      <mesh>
        <cylinderGeometry args={[1.2, 1.55, 0.75, 6]} />
        <meshStandardMaterial color="#6b7182" metalness={0.9} roughness={0.38} emissive="#1b2940" emissiveIntensity={0.45} flatShading />
      </mesh>
      <mesh position={[0, 0.66, 0]} rotation={[Math.PI / 2, 0, 0]}>
        <cylinderGeometry args={[0.16, 0.2, 1.7, 8]} />
        <meshStandardMaterial color="#db624d" metalness={0.8} roughness={0.28} emissive="#591d20" emissiveIntensity={0.9} />
      </mesh>
    </group>
  )
}

function Carrier({ group, phase }: { group: React.RefObject<THREE.Group | null>; phase: number }) {
  const coreColor = phase === 2 ? '#fff06a' : phase === 1 ? '#ff9f55' : '#ff514d'
  return (
    <group ref={group} scale={1.5}>
      <mesh>
        <boxGeometry args={[6.8, 2.5, 8]} />
        <meshStandardMaterial color="#6d8298" metalness={0.92} roughness={0.3} emissive="#162b4d" emissiveIntensity={0.75} flatShading />
      </mesh>
      <mesh position={[0, 1.5, -1.2]}>
        <boxGeometry args={[4.5, 0.5, 4.2]} />
        <meshStandardMaterial color="#a5b7c3" metalness={0.88} roughness={0.25} emissive="#234c66" emissiveIntensity={0.72} flatShading />
      </mesh>
      <mesh position={[0, 0, -4.2]}>
        <boxGeometry args={[2.8, 1.2, 0.3]} />
        <meshBasicMaterial color={coreColor} toneMapped={false} />
      </mesh>
      <mesh position={[-2.6, 0.2, -0.8]} rotation={[0, 0, Math.PI / 2]}>
        <coneGeometry args={[0.5, 3.2, 4]} />
        <meshStandardMaterial color="#8ca1ae" metalness={0.95} roughness={0.28} flatShading />
      </mesh>
      <mesh position={[2.6, 0.2, -0.8]} rotation={[0, 0, -Math.PI / 2]}>
        <coneGeometry args={[0.5, 3.2, 4]} />
        <meshStandardMaterial color="#8ca1ae" metalness={0.95} roughness={0.28} flatShading />
      </mesh>
      <mesh position={[0, 0, -4.38]}>
        <sphereGeometry args={[0.72, 16, 8]} />
        <meshBasicMaterial color={coreColor} toneMapped={false} />
      </mesh>
      <pointLight color={coreColor} intensity={phase === 2 ? 5 : 3.2} distance={9} />
    </group>
  )
}

